// Source of truth: logic/hours.js (unit tested in tests/hours.test.js).
// Timezone comes from config, not from the server clock. Do not "simplify" this
// to new Date().getHours() - that silently answers in the instance timezone.
const HOURS_DEFAULTS = {
  timezone: 'UTC',
  business_days: [1, 2, 3, 4, 5],
  business_start_hour: 9,
  business_end_hour: 17,
  quiet_start_hour: 21,
  quiet_end_hour: 8
};
const cfg = Object.assign({}, HOURS_DEFAULTS, {
  timezone: $env.BUSINESS_TIMEZONE || HOURS_DEFAULTS.timezone,
  business_start_hour: Number($env.BUSINESS_START_HOUR || HOURS_DEFAULTS.business_start_hour),
  business_end_hour: Number($env.BUSINESS_END_HOUR || HOURS_DEFAULTS.business_end_hour)
});

function localParts(when) {
  const fmt = new Intl.DateTimeFormat('en-US', { timeZone: cfg.timezone, hour12: false,
    weekday: 'short', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' });
  const p = {};
  fmt.formatToParts(new Date(when)).forEach((x) => { p[x.type] = x.value; });
  const dow = { Sun: 0, Mon: 1, Tue: 2, Wed: 3, Thu: 4, Fri: 5, Sat: 6 }[p.weekday];
  return { year: +p.year, month: +p.month, day: +p.day, hour: (+p.hour) % 24, minute: +p.minute, dow };
}
function fromLocal(parts) {
  const guess = Date.UTC(parts.year, parts.month - 1, parts.day, parts.hour, parts.minute || 0);
  let ts = guess;
  for (let i = 0; i < 3; i++) {
    const p = localParts(new Date(ts));
    const actual = Date.UTC(p.year, p.month - 1, p.day, p.hour, p.minute);
    const drift = actual - guess;
    if (drift === 0) break;
    ts -= drift;
  }
  return new Date(ts);
}
function isOpen(when) {
  const p = localParts(when);
  return cfg.business_days.includes(p.dow) && p.hour >= cfg.business_start_hour && p.hour < cfg.business_end_hour;
}
function nextOpen(when) {
  if (isOpen(when)) return new Date(when);
  let p = localParts(when);
  for (let i = 0; i < 14; i++) {
    if (i === 0 && cfg.business_days.includes(p.dow) && p.hour < cfg.business_start_hour) {
      return fromLocal({ year: p.year, month: p.month, day: p.day, hour: cfg.business_start_hour, minute: 0 });
    }
    const noon = fromLocal({ year: p.year, month: p.month, day: p.day, hour: 12, minute: 0 });
    p = localParts(new Date(noon.getTime() + 24 * 3600 * 1000));
    if (cfg.business_days.includes(p.dow)) {
      return fromLocal({ year: p.year, month: p.month, day: p.day, hour: cfg.business_start_hour, minute: 0 });
    }
  }
  throw new Error('No open window in 14 days - check business_days config.');
}

const now = new Date();
return $input.all().map((item) => {
  const lead = item.json.lead || item.json;
  const open = isOpen(now);
  return { json: Object.assign({}, item.json, {
    lead,
    within_hours: open,
    send_after: open ? now.toISOString() : nextOpen(now).toISOString(),
    channel: lead.channel || lead.source_channel || (lead.email ? 'email' : (lead.phone ? 'sms' : 'dm'))
  }) };
});

